class Solution {
    private int gap(int length,int[] cuts){
        Arrays.sort(cuts);
        int previous=0,maximum=0;
        for(int cut:cuts){
            maximum=Math.max(maximum,cut-previous);
            previous=cut;
        }
        return Math.max(maximum,length-previous);
    }
    public int maxArea(int h,int w,int[] horizontalCuts,int[] verticalCuts){
        return (int)((long)gap(h,horizontalCuts)*gap(w,verticalCuts)%1_000_000_007L);
    }
}

code.kotlin:
class Solution {
    private fun gap(length:Int,cuts:IntArray):Int{
        cuts.sort();
        var previous=0;
        var maximum=0;
        for(cut in cuts){
            maximum=maxOf(maximum,cut-previous);
            previous=cut
        };
        return maxOf(maximum,length-previous)
    };
    fun maxArea(h:Int,w:Int,horizontalCuts:IntArray,verticalCuts:IntArray):Int=(gap(h,horizontalCuts).toLong()*gap(w,verticalCuts)%1_000_000_007L).toInt()
}

